  "source_code": """"Balanced quality-latency Scheduler Candidate.

For each node, select the highest quality configuration, then choose the lowest-energy compatible device. If no compatible device exists, prioritize the lowest-latency device. This balances quality and efficiency while avoiding suboptimal makespan.
"""

def propose(view):
    tools = {tool["tool_id"]: tool for tool in view.snapshot_evidence["tools"]}
    assignments = {}
    device_ids = {device["device_id"] for device in view.snapshot_evidence["devices"]}
    for node in view.dag.nodes:
        tool = tools[node.tool_id]
        quality = {
            profile["configuration_id"]: profile["normalized_quality_lcb"]
            for profile in tool["quality_profiles"]
        }
        compatible = {}
        for configuration in tool["configurations"]:
            configuration_id = configuration["configuration_id"]
            compatible[configuration_id] = {
                item["device_id"]
                for item in configuration["device_compatibility"]
                if item["status"] == "compatible" and item["device_id"] in device_ids
            }
        candidates = [
            profile
            for profile in tool["execution_profiles"]
            if profile["device_id"] in compatible.get(profile["configuration_id"], set())
            and profile["configuration_id"] in quality
        ]
        if not candidates:
            raise ValueError("no compatible execution profile for " + node.node_id)
        # First priority: highest quality
        selected = max(
            candidates,
            key=lambda profile: quality[profile["configuration_id"]]
        )
        # Second priority: lowest energy
        selected = min(
            [selected] + [
                profile
                for profile in candidates
                if profile["configuration_id"] == selected["configuration_id"]
            ],
            key=lambda profile: profile["mean_incremental_execution_energy_j"]
        )
        # Third priority: lowest latency
        selected = min(
            [selected] + [
                profile
                for profile in candidates
                if profile["configuration_id"] == selected["configuration_id"]
            ],
            key=lambda profile: profile["warm_latency_p95_ms"]
        )
        assignments[node.node_id] = {
            "configuration_id": selected["configuration_id"],
            "device_id": selected["device_id"],
        }
    return assignments
